def get_world_news():
    """Get world news from major news outlets"""
    sources = [
        ('BBC World', 'https://www.bbc.com/news/world'),
        ('CNN World', 'https://www.cnn.com/world'),
        ('Reuters World', 'https://www.reuters.com/world'),
        ('Al Jazeera English', 'https://www.aljazeera.com/news')
    ]

    articles = []
    for name, url in sources:
        try:
            response = requests.get(url, timeout=8)
            if response.status_code == 200:
                from bs4 import BeautifulSoup
                soup = BeautifulSoup(response.text, 'html.parser')

                # Find news items - different sites have different structures
                news_items = []
                if 'bbc' in url:
                    news_items = soup.select('div.gs-c-promo')[:2]
                elif 'cnn' in url:
                    news_items = soup.select('div.cnn-search__result-left')[:2]
                elif 'reuters' in url:
                    news_items = soup.select('article.story')[:2]
                elif 'aljazeera' in url:
                    news_items = soup.select('div.article-body')[:2]
                else:
                    # Generic fallback
                    news_items = soup.find_all(['article', 'div'], class_=re.compile('news|article', re.I))[:2]

                for item in news_items:
                    headline_elem = item.find(['h2', 'h3', 'h4', 'a', 'span'])
                    if headline_elem:
                        headline = headline_elem.get_text(strip=True)
                        summary_elem = item.find(['p', 'div'])
