def get_sports_updates():
    """Get sports updates for specified teams"""
    sports_data = {}
    teams = {
        'Michigan State University': 'https://www.msuspartans.com/sports',
        'University of Michigan': 'https://www.mgoblue.com/sports',
        'Tampa Bay Rowdies': 'https://www.rowdiessoccer.com/schedule',
        'St. Petersburg': 'https://www.rowdiessoccer.com/schedule'
    }

    for team_name, url in teams.items():
        try:
            response = requests.get(url, timeout=8)
            if response.status_code == 200:
                from bs4 import BeautifulSoup
                soup = BeautifulSoup(response.text, 'html.parser')

                # Try to find upcoming games
                games = []
                if 'spartans' in url or 'michigan' in url:
                    # College sports - look for schedule
                    schedule = soup.find('table', class_=re.compile('schedule|stats'))
                    if schedule:
                        rows = schedule.find_all('tr')[1:4]  # Next 3 games
                        for row in rows:
                            cols = row.find_all('td')
                            if len(cols) >= 2:
                                opponent = cols[1].get_text(strip=True)
                                time = cols[2].get_text(strip=True) if len(cols) > 2 else "TBD"
                                games.append(f"vs {opponent} - {time}")
                elif 'rowdies' in url:
                    # Soccer - look for matches
                    matches = soup.find_all('div', class_=re.compile('match|game'))[:3]
                    for match in matches:
                        teams_elem = match.find(class_=re.compile('teams'))
                        if teams_elem:
                            teams_text = teams_elem.get_text(strip=True)
                            time_elem = match.find(class_=re.compile('time|date'))
                            time_text = time_elem.get_text(strip=True) if time_elem else "TBD"
                            games.append(f"{teams_text} - {time_text}")

                if games:
                    sports_data[team_name] = games
        except:
            continue

    return sports_data

